// Keep navigation generated by the shared footer within this set of review pages.
for (const link of document.querySelectorAll('.aral-global-footer a[href]')) {
  const href = link.getAttribute('href');
  if (/^(?:[a-z]+:|\/\/|#)/i.test(href)) continue;
  link.setAttribute('href', href.replace('line-sidebar-preview.html', 'markup-preview.html')
                                .replace('line_sidebar_preview.html', 'markup_preview.html'));
}
